"""Face set (all art generated by ChatGPT, family B: wide rounded head). This script only cuts the
background out and crops every frame to one common box. Run: python3 design/build_faces.py"""
import numpy as np, os
from PIL import Image, ImageFilter
from scipy import ndimage as ndi
R=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT=os.path.join(R,'android/app/src/main/res/drawable-nodpi/')
SRC={  # name: raw ChatGPT render
 'calm':'g1','stern':'h2','angry':'h3','rage':'h0','sad':'f3','bored':'h1','look_dl':'g0','look_dc':'g1','look_dr':'g2'}
ALIAS={'worried':'calm','sad':'look_dc','sleepy':'bored','happy':'calm'}   # until ChatGPT image quota resets (calm/happy/worried/sleepy to be generated)
def cut(p):
    im=Image.open(os.path.join(R,'assets/faces',p+'.png')).convert('RGB'); a=np.asarray(im).astype(float)
    bg=np.median(np.concatenate([a[:20,:20].reshape(-1,3),a[:20,-20:].reshape(-1,3)]),axis=0)
    m=np.sqrt(((a-bg)**2).sum(2))>45
    m=ndi.binary_opening(m,iterations=2); lab,k=ndi.label(m); s=ndi.sum(m,lab,range(1,k+1)); m=lab==(1+int(np.argmax(s)))
    m=ndi.binary_fill_holes(ndi.binary_closing(m,iterations=6))
    # steam puffs are separate blobs; keep any blob that is not tiny so they stay in the art
    full=m
    ys,xs=np.where(m)
    return im,full,(xs.min(),xs.max(),ys.min(),ys.max())
cut_all={n:cut(p) for n,p in SRC.items()}
side=int(np.median([max(b[1]-b[0],b[3]-b[2]) for _,_,b in cut_all.values()])*1.12)
for n,(im,full,b) in cut_all.items():
    cx,cy=(b[0]+b[1])//2,(b[2]+b[3])//2
    mi=Image.fromarray((ndi.binary_fill_holes(full)*255).astype('uint8')).filter(ImageFilter.GaussianBlur(1.4))
    rgba=im.convert('RGBA'); rgba.putalpha(mi)
    box=(cx-side//2,cy-side//2,cx+side//2,cy+side//2)
    rgba.crop(box).resize((384,384),Image.LANCZOS).save(OUT+f'head_{n}.png')
for a,t in ALIAS.items(): Image.open(OUT+f'head_{t}.png').save(OUT+f'head_{a}.png')
print('built',sorted(list(SRC)+list(ALIAS)))
